'use strict';
// Presentation only: never write to the original itinerary objects.
const journeyToday=()=>tripToday(new Date(),DATA.days,tripCalendarChanges).day;
const journeyTitle=(d,r)=>d.id===3&&r.stepTitle==='桑拿备选'?'酒店泡浴':r.stepTitle||'行程安排';
const journeyStages=[['1','出发 · 赫尔辛基'],['2,3,4,5','特罗姆瑟'],['6,7,8','罗弗敦'],['9','博德 → 奥斯陆'],['10','抵达冰岛'],['11','南岸 → 维克'],['12,13','冰河湖 · Hali'],['14','黄金圈'],['15','Silfra → 雷克雅未克'],['16','哥本哈根'],['17','返程 · 赫尔辛基'],['18','北京']];
function journeyDate(value=state.day,mapMode=false){return `<label class="journey-date"><span>日期</span><select data-journey-date="${mapMode?'map':'day'}" aria-label="${mapMode?'地图日期':'行程日期'}">${DATA.days.map(d=>`<option value="${d.id}" ${d.id===+value?'selected':''}>${shortDate(d.date)} · ${d.title}</option>`).join('')}</select></label>`;}
function journeyPosition(d,now=new Date(),rows=selectedPlan(d)){
 const pos=planPosition(d,now,rows),time=+now;
 const past=rows.map((r,i)=>{const w=stepWindow(d,r);if(!w)return /前一晚/.test(r.time);if(w.end!==null)return time>=w.end;const next=rows.slice(i+1).map(x=>stepWindow(d,x)).find(x=>x&&x.start>w.start);return !!next&&time>=next.start;});
 if(!pos.live)return {...pos,past:rows.map(()=>false),primary:0,following:rows.length>1?1:-1};
 let primary=pos.current>=0?pos.current:pos.approximate>=0?pos.approximate:pos.next;
 // Keep unclocked actions between the last elapsed window and next timed action.
 const lastEnded=rows.reduce((a,r,i)=>past[i]?i:a,-1);
 if(primary>lastEnded+1&&lastEnded>=0)primary=lastEnded+1;
 if(primary<0&&lastEnded<rows.length-1)primary=lastEnded+1;
 return {...pos,past,primary,following:primary>=0&&primary+1<rows.length?primary+1:-1};
}
function journeyAction(d,index,label,homeMode=false){const rows=selectedPlan(d),r=rows[index];return `<article class="journey-action"><p class="editor-label">${label}${homeMode?' · '+shortDate(d.date):''}</p>${r?`<h2>${esc(journeyTitle(d,r))}</h2><p class="journey-action-time">${esc(r.time)}</p><button ${homeMode?'data-day="'+d.id+'" data-focus-step="'+index+'"':'data-step-focus="'+index+'"'}>查看安排 →</button>`:`<h2>当天安排已到尾声</h2><button data-day="${Math.min(18,d.id+1)}">${d.id<18?'查看明天 →':'查看返程安排 →'}</button>`}</article>`;}
timeCard=function(d,now=new Date()){const p=journeyPosition(d,now);return `<div class="journey-actions">${journeyAction(d,p.primary,p.live?(p.current>=0?'当前计划':p.approximate>=0?'当前安排 · 约定时段':'接下来'):'当天第一段')}${journeyAction(d,p.following,'随后')}</div>`;};
routeOverview=function(){return `<section class="home-route"><div><p class="editor-label">18天 · 全程路线</p><p class="route-sentence">北京 → 赫尔辛基 → 特罗姆瑟 → 罗弗敦 → 博德 → 奥斯陆 → 冰岛 → 哥本哈根 → 赫尔辛基 → 北京</p><p class="experience-line">观鲸 · 峡湾海岸 · 温泉 · 冰河湖 · 蓝冰洞 · Silfra浮潜</p><button class="action-button" data-mapday="all">查看全程路线 ↗</button></div><button class="home-atlas" data-mapday="all" aria-label="打开全程路线">${atlas()}</button></section>`;};
function homeDaySummary(d,label,isCurrent=false){const rows=selectedPlan(d),pos=journeyPosition(d),start=isCurrent&&pos.live?Math.max(0,pos.primary):0;const score=r=>/飞|航班|追鲸|冰湖快艇|蓝冰洞|峡谷浮潜|缆车上山|温泉|桑拿备选|酒店泡浴/.test(r.stepTitle||'')?5:/蓝调|隧道放行|隧道通行|渔村漫步|海鲜午餐|红屋拍照|四晚采购|黄金瀑布|间歇泉|新港|抵达北京/.test(r.stepTitle||'')?4:/酒店入住|公寓入住|小屋入住|托运候机|市区购物|白沙滩|前往机场/.test(r.stepTitle||'')?3:/早餐|休息|整理|路线选择/.test(r.stepTitle||'')?-1:1;const future=rows.slice(start).map((r,i)=>({r,i:i+start,score:score(r)})).sort((a,b)=>b.score-a.score||a.i-b.i);let picked=future.slice(0,isCurrent&&pos.live?2:3);if(isCurrent&&pos.live){picked=future.filter(x=>x.i!==start).slice(0,2);picked.push({r:rows[start],i:start});}const items=isCurrent&&pos.live&&pos.primary<0?[]:picked.filter(x=>x.r).sort((a,b)=>a.i-b.i).map(x=>x.r),key=items.map(r=>r.stepTitle).join('|');return `<article class="home-day-summary" data-summary-key="${d.id}:${key}"><header><p>${label} · ${shortDate(d.date)}</p><button data-day="${d.id}">完整日程 →</button></header><h2>${esc(d.title)}</h2><p class="home-summary-route">${highlights(d).slice(0,3).map(esc).join(' · ')||esc((d.flights||[]).map(f=>f[1]+' → '+f[4]).join(' · ')||d.region)}</p><ul>${items.map(r=>`<li><time>${esc(r.time)}</time><span>${esc(journeyTitle(d,r))}</span></li>`).join('')||'<li>当天安排已到尾声</li>'}</ul></article>`;}
function homeSummaries(t=tripToday(new Date(),DATA.days,tripCalendarChanges)){const d=DATA.days[t.day-1],before=t.boundary==='first';return homeDaySummary(d,before?'出发日':t.inTrip?'今天':'最后一天',t.inTrip)+(d.id<18?homeDaySummary(DATA.days[d.id],before?'次日':'明天'):'');}
home=function(){const t=tripToday(new Date(),DATA.days,tripCalendarChanges),d=DATA.days[t.day-1],before=t.boundary==='first',days=Math.max(0,Math.ceil((tripLocalTimestamp(DATA.days[0].date,'00:00','Asia/Shanghai')-Date.now())/86400000));return `<section class="journal-hero journey-hero"><img src="${pImage('hamnoy')}" width="1176" height="805" alt="Hamnøy红屋与罗弗敦山海" fetchpriority="high" decoding="async"><div class="hero-copy"><p>2026.10.18 — 11.04 · 挪威与冰岛</p><h1>Nordic Journal <em>2026</em></h1><div class="home-date-entry">${journeyDate(t.day)}<button data-open-home-day aria-label="查看所选日期行程">查看日程 →</button></div></div></section><section class="journey-home-status"><header><span>${before?'距出发 '+days+' 天':t.inTrip?'今天与明天的安排':'旅程回顾'}</span><button data-view="itinerary">全部日期 →</button></header><div class="home-summaries">${homeSummaries(t)}</div></section>${routeOverview()}<footer class="journal-footer"><span>Nordic Journal 2026</span><div><button data-credits>照片来源</button><button data-offline>离线资料</button><button data-top>回到顶部 ↑</button></div></footer>`;};
const countryCompactDays=compactDays;
compactDays=function(filter=browseSearch,region=browseCountry){if(region==='all'||['挪威','冰岛','transfer'].includes(region))return countryCompactDays(filter,region);const allowed=region.split(',').map(Number),html=countryCompactDays(filter,'all'),template=document.createElement('template');template.innerHTML=html;template.content.querySelectorAll('.compact-day').forEach(el=>{if(!allowed.includes(+el.querySelector('[data-day]').dataset.day))el.remove();});template.content.querySelectorAll('.phase-title').forEach(el=>{if(!el.nextElementSibling?.classList.contains('compact-day'))el.remove();});return template.innerHTML||'<p class="empty-state">没有匹配的安排。</p>';};
itineraryView=function(){return `<header class="utility-header"><p class="editor-label">18 OCT — 04 NOV 2026</p><h1>全程日程</h1><label class="journey-date"><span>旅程阶段</span><select data-journey-stage aria-label="按实际旅程顺序筛选"><option value="all">完整旅程</option>${journeyStages.map(([k,n])=>`<option value="${k}" ${browseCountry===k?'selected':''}>${n}</option>`).join('')}</select></label><label class="destination-search">${ico('pin')}<input id="destinationSearch" type="search" value="${esc(browseSearch)}" placeholder="目的地、日期或航班" aria-label="搜索行程"></label><p class="search-count" id="searchCount" role="status">按旅程先后排列</p></header><div id="compactIndex">${compactDays()}</div>`;};
function journeyParking(key){const p=TRAVEL_SUPPORT.placeParking(key);return p?`<button data-parking="${esc(key)}">停车与缴费</button>`:'';}
function travellerNotes(d){let text=d.notes||'';text=text.replace(/酒店入住开始时间待核对/g,'入住时间请向酒店确认').replace(/Å镇精确日照待补，不能套成分钟级当地结果。/g,'这里的日照时间以莱克内斯区域为参考。').replace(/当天具体日出日落待补核，/g,'').replace(/先列待订备选，未预订/g,'安排泡浴，需提前预约').replace(/Arctic Wellness待订备选/g,'Arctic Wellness酒店泡浴，需提前预约').replace(/待路线最终确认后细化/g,'实际以当日道路及导航为准').replace(/后续确认性总结直接推进，只有实质取舍才提问。/g,'').replace(/用户已确定的内容：|用户已确认：|餐饮已确认：/g,'').replace(/用户已确认加入Nusfjord。/g,'当天保留Nusfjord游览。').replace(/具体交通仍待确认/g,'出发前查看公交停站，返程可叫出租车').replace(/尚待核实|尚未核实|尚未核验|待核实|待核对|待补核|待补充|待订/g,'请提前确认').replace(/未核实/g,'请出发前确认');
 // Repeated itinerary tables are already represented by the interactive timeline.
 text=text.replace(/(?:^|\n)\|[^\n]*(?:时间|当地时间)[^\n]*\|[\s\S]*?(?=\n\n|$)/g,'');
 text=text.replace(/^### (建议时间线|固定信息与共同上午)\s*$/gm,'');return text;}
function journeyStepNotes(d,rows){const result=rows.map(()=>[]),left=[];for(const block of travellerNotes(d).split(/\n\n+/)){if(!block.trim())continue;let index=-1;const themes=[[/Arctic Wellness|共享场90分钟/,/桑拿备选/],[/Nappstraumtunnelen|Flesa|引导通行/,/隧道排队|前往隧道/],[/Tromsøbrua|大桥施工/,/教堂外观/],[/Blue当前|Comfort：|Blue票|Blue营业|四个20–28寸/,/Blue温泉/],[/Saman|Skjól|七步|Sky票/,/Sky温泉/],[/Full Steam|特色餐厅|餐厅菜单/,/晚餐/],[/四晚|保温袋|食材/,/四晚采购/]];for(const [content,title] of themes){if(content.test(block)){index=rows.findIndex(r=>title.test(r.stepTitle||''));if(index>=0)break;}}if(index>=0)result[index].push(block);else left.push(block);}return {rows:result.map(x=>x.join('\n\n')),tail:left.join('\n\n')};}
function journeyPlace(k){const p=DATA.places[k],src=smallPhoto(k);if(!p)return '';return `<details class="journey-disclosure place-inline"><summary>${esc(p.name)} · 简介${src?'与照片':''}</summary><div class="journey-detail-body">${src?`<button class="journey-place-image" data-photo="${k}" aria-label="全屏查看${esc(p.name)}"><img src="${src}" width="720" height="480" alt="${esc(p.name)}" loading="lazy" decoding="async"></button>`:''}<p>${inline(travellerNotes({notes:p.desc||''}))}</p>${p.hours?`<p class="place-hours">${inline(travellerNotes({notes:p.hours}))}</p>`:''}${p.source?ext(p.source,'地点官网与游览说明','small-link'):''}${p.stay?`<p class="info-caption">停留 ${esc(p.stay)}</p>`:''}${p.tips?.length?`<ul>${p.tips.map(x=>'<li>'+inline(travellerNotes({notes:x}))+'</li>').join('')}</ul>`:''}</div></details>`;}
function journeyAssociations(d,rows){const sets=rows.map(()=>[]),keys=[...new Set([...selectedSpots(d),...(d.venues||[])])];for(const key of keys){const p=DATA.places[key];if(!p)continue;const terms=[p.name,p.en,key.length>4?key:''].filter(Boolean);let best=-1,score=0;rows.forEach((r,i)=>{let n=(r.nav||[]).includes(key)?20:0;if(terms.some(x=>r.text.includes(x)||r.stepTitle?.includes(x)))n+=8;if(/漫步|拍照|午餐|购物|观景|海岸|沙滩|瀑布|泡浴|缆车|间歇泉/.test(r.stepTitle))n+=5;if(/前往|通行|排队|自驾|返回|寄存|放行/.test(r.stepTitle))n-=12;if(n>score){best=i;score=n;}});if(best<0||score<8){const fallback={3:'逛街',5:'超市补给',7:'山湖漫步',9:'市区购物',11:'四晚采购',13:'返回Hali',15:'纪念品购物',16:'市区购物'}[d.id];best=rows.findIndex(r=>r.stepTitle===fallback);}if(best>=0)sets[best].push(key);}return sets;}
function dayEndRecommendation(d,pos=journeyPosition(d)){if(!pos.live||pos.primary>=0)return '';return `<section class="day-end-recommendation"><p class="day-end-note">${d.id<18?'今天的计划已到尾声，看看明天的安排。':'十八天的计划已到尾声，可以回看整段旅程。'}</p>${d.id<18?homeDaySummary(DATA.days[d.id],'明日安排'):'<button data-view="itinerary">回看完整旅程 →</button>'}</section>`;}
