function journeyRowCopy(d,r,s){const key=d.id+':'+r.stepTitle;if(Object.hasOwn(JOURNEY_ROW_COPY,key))return JOURNEY_ROW_COPY[key];return travellerNotes({notes:r.text}).replace(/；起降均为当地时间。|；起降均为当地时间|均为当地时间。/g,'');}
function journeyCriticalCopy(c,r){const fixed=/原定还车|原定取车/.test(c.basis),label=/班次/.test(c.basis)?'班次':fixed?'原定':/关闭/.test(c.basis)?'计划':'目标',same=c.time.replace(/\s/g,'')===r.time.replace(/\s/g,''),basis=/运营商|至少提前|官网|电子票|当日通知|公告/.test(c.basis)?c.basis.replace('原资料：','').replace('原计划班次；','').replace('计划提前','预留'):'';return `<p class="journey-critical"><span aria-hidden="true">!</span><strong>${label}${same?'':' '+esc(c.time)}</strong> ${esc(c.action)}${basis?'<small>'+esc(basis)+'</small>':''}</p>`;}
renderTimeline=function(d){const rows=selectedPlan(d),pos=journeyPosition(d),stay=stayRow(d,rows),pictures=journeyAssociations(d,rows),stepNotes=journeyStepNotes(d,rows),branch=d.variants?.[state.variants[d.id]||'A']?.timeline||[],firstBranch=rows.findIndex(r=>branch.includes(r)),decision=rows.findIndex(r=>r.stepTitle==='路线选择');const rowHTML=(r,i)=>{const s=TRAVEL_SUPPORT.row(d,r);if(d.id===3&&r.stepTitle==='桑拿备选')s.reminder='提前至少2小时向酒店预约20:00泡浴；需16岁以上，90分钟400 NOK/人。留意下山与晚餐衔接。';const b=DATA.bookings.find(b=>b.day===d.id&&bookingRow(d,b,rows)===i),critical=s.critical.length;return `<article id="step-${i}" data-row-index="${i}" class="timeline-row ${critical?'time-critical':''} ${pos.primary===i&&pos.live?'is-current':''}"><div class="timeline-time">${inline(r.time)}${timelineClockLabel(d,r)?`<small>${esc(timelineClockLabel(d,r))}</small>`:''}</div><div class="timeline-text"><div class="timeline-heading"><h3 class="step-title"><span class="step-icon" data-step-kind="${journeyStepKind(r)}">${journeyTravelIcon(journeyStepKind(r))}</span><span>${esc(journeyTitle(d,r))}</span></h3><span class="step-state">${pos.live&&pos.primary===i?(pos.current>=0?'当前计划':pos.approximate>=0?'当前安排':'接下来'):pos.live&&pos.following===i?'随后':''}</span></div>${s.durations.filter(x=>x.kind!=='计划时段').length?`<p class="step-duration">${s.durations.filter(x=>x.kind!=='计划时段').map(x=>esc(x.kind)+' '+esc(x.label)).join(' · ')}</p>`:''}${s.critical.map(c=>journeyCriticalCopy(c,r)).join('')}${journeyRowCopy(d,r,s)?`<p class="step-description">${inline(journeyRowCopy(d,r,s))}</p>`:''}${d.variants&&i===decision?routeChoice(d):''}${b?`<details class="journey-disclosure"><summary>活动票与集合说明</summary><div class="journey-detail-body">${bookingInline(b)}</div></details>`:''}${i===stay?`<details class="journey-disclosure" id="todayStay"><summary>今晚住宿 · ${esc(DATA.hotels[d.hotel]?.cn)}</summary><div class="journey-detail-body">${hotelQuick(d)}</div></details>`:''}<div class="step-locations">${(r.nav||[]).filter(k=>!k.startsWith('hotel:')).map(k=>`<button data-step-map="${i}" data-map-key="${k}">${esc(DATA.places[k]?.name||k)} · 地图</button>`).join('')}${(r.nav||[]).length?`<button data-navigation="${r.nav[0]}">导航 ↗</button>`:''}${s.parking.map(p=>journeyParking(p.placeKey)).join('')}</div>${pictures[i].map(journeyPlace).join('')}${stepNotes.rows[i]?`<details class="journey-disclosure"><summary>这一段的实用说明</summary><div class="journey-detail-body rich">${markdown(stepNotes.rows[i])}</div></details>`:''}${d.id===13&&r.stepTitle==='蓝冰洞'?'<details class="journey-disclosure"><summary>留守同伴 · Hali附近</summary><div class="journey-detail-body"><p>优先酒店旁Þórbergssetur书墙与文化馆；外观10–15分钟，开放时入内45–60分钟。咖啡馆常规11:00–15:00，入内时段向前台了解。只走酒店周边平坦短路，风雨大时留室内；不步行前往冰河湖。</p></div></details>':''}${d.id===15&&r.stepTitle==='峡谷浮潜'?'<details class="journey-disclosure"><summary>留守同伴 · 集合点附近</summary><div class="journey-detail-body"><p>在P5与集合点附近等候，可沿安全步道看教堂和农舍外观，往返约30–45分钟。保留车钥匙和保暖衣物；地面结冰、强风时回车内，不独自远走峡谷或沿车道步行。</p></div></details>':''}</div></article>`;};let html='',i=0;while(i<rows.length){if(pos.past[i]&&pos.live){const start=i;while(i<rows.length&&pos.past[i])i++;html+=`<details class="journey-disclosure past-steps"><summary>此前安排 · ${i-start}项 <span>展开查看</span></summary><div class="journey-detail-body">${rows.slice(start,i).map((r,j)=>rowHTML(r,start+j)).join('')}</div></details>`;}else{if(d.variants&&decision<0&&i===firstBranch)html+=`<section class="timeline-decision"><p class="decision-heading">接下来 · 选择安排</p>${routeChoice(d)}</section>`;html+=rowHTML(rows[i],i);i++;}}return `<div class="timeline">${html}<div id="dayEndPreview">${dayEndRecommendation(d,pos)}</div></div>`;};
extraDay=function(d){return `<div class="day-closing-notes"><p class="info-caption">日出约 ${esc(d.sun[0])} · 日落约 ${esc(d.sun[1])}</p>${d.alternatives?.filter(a=>!(d.id===3&&a.name?.includes('Arctic Wellness'))).length?`<details class="journey-disclosure"><summary>备选安排</summary><div class="journey-detail-body">${d.alternatives.filter(a=>!(d.id===3&&a.name?.includes('Arctic Wellness'))).map(a=>typeof a==='string'?'<p>'+inline(a)+'</p>':'<p>'+esc(a.name||a.title||'')+' '+esc(a.text||a.desc||'')+'</p>').join('')}</div></details>`:''}<details class="journey-disclosure"><summary>当天餐饮与其他提醒</summary><div class="journey-detail-body"><p>${inline(d.meal||'')}</p><p>${inline(d.drive||'')}</p>${d.alert?'<p>'+inline(d.alert)+'</p>':''}${markdown(journeyStepNotes(d,selectedPlan(d)).tail)}</div></details></div>`;};
dayView=function(){const d=DATA.days[state.day-1],t=tripToday(new Date(),DATA.days,tripCalendarChanges),zone=t.inTrip&&t.day===d.id?t.zone:d.tz;return `<header class="utility-header day-utility"><div class="day-meta-line"><p class="editor-label">${shortDate(d.date)} ${new Intl.DateTimeFormat("zh-CN",{weekday:"short",timeZone:"UTC"}).format(new Date(d.date+"T12:00:00Z")).replace("星期","周")}</p><div class="day-clock" data-compact-clock><span>${esc(zoneLabel(zone).replace("北京时间","北京").replace("时间",""))} <time data-clock-zone="${zone}"></time></span>${zone!=="Asia/Shanghai"?'<span>北京 <time data-clock-zone="Asia/Shanghai"></time></span>':""}</div></div><h1>${esc(d.title)}</h1></header><nav class="day-top-controls" aria-label="切换行程日期">${journeyDate(d.id)}<button data-day="${d.id+1}" ${d.id===18?'disabled':''}>后一天 →</button></nav><div class="utility-actions"><button data-mapday="${d.id}">当天地图 ↗</button><button data-view="itinerary">完整日程</button>${d.hotel?'<button data-scroll-id="todayStay">今晚住宿 ↓</button>':''}</div>${WEATHER_SERVICE.renderShell(d,selectedPlan(d))}<section class="section day-timeline" aria-label="当天动态时间线"><div id="planTimeline">${renderTimeline(d)}</div></section><div id="dayExtras" data-spots="${esc(selectedSpots(d).join('|'))}">${extraDay(d)}</div>${dayPagination(d)}`;};
toolNames.lists='厨房采购';
function journeyToolGroups(entries){const t=journeyToday(),now=Date.now(),elapsed=x=>Number.isFinite(x.endAt)?x.endAt<now:x.end<t,started=x=>Number.isFinite(x.startAt)?x.startAt<=now:x.start<=t,past=entries.filter(elapsed),upcoming=entries.filter(x=>!elapsed(x)),present=upcoming.filter(started),next=upcoming.filter(x=>!started(x));return `${present.length?'<h3 class="tool-period">当前要用</h3>'+present.map(x=>x.html).join(''):''}${next.length?'<h3 class="tool-period">接下来的安排</h3>'+next.map(x=>x.html).join(''):''}${past.length?`<details class="journey-disclosure past-tools"><summary>此前安排 · ${past.length}项</summary><div class="journey-detail-body">${past.map(x=>x.html).join('')}</div></details>`:''}`||'<p class="empty-state">这一天没有相应安排。</p>';}
function journeyBookingWindow(b){const d=DATA.days[b.day-1],title={4:'追鲸',12:'冰湖快艇',13:'蓝冰洞',15:'峡谷浮潜'}[b.day],r=selectedPlan(d).find(r=>r.stepTitle===title);return r?stepWindow(d,r):stepWindow(d,{time:b.time,text:''});}
const previousToolBody=toolBody;
toolBody=function(k){const days=toolDay==='all'?DATA.days:DATA.days.filter(d=>d.id===+toolDay);if(k==='activities')return journeyToolGroups(DATA.bookings.filter(b=>days.some(d=>d.id===b.day)).map(b=>({start:b.day,end:b.day,startAt:journeyBookingWindow(b)?.start,endAt:journeyBookingWindow(b)?.end,html:bookingQuick(b)})));if(k==='flights')return journeyToolGroups(days.flatMap(d=>(d.flights||[]).map(f=>{const r=selectedPlan(d).find(r=>r.text.includes(f[0])&&stepTimeZones(d,r).flight),w=r?stepWindow(d,r):null;return {start:d.id,end:d.id,startAt:w?.start,endAt:w?.end,html:`<article class="tool-flight"><h3>${dateText(d.date)}</h3><div class="flights">${flight(f)}</div><button class="small-link" data-day="${d.id}">当天交通安排 →</button></article>`};})));if(k==='hotels')return journeyToolGroups([...new Set(days.map(d=>d.hotel).filter(Boolean))].map(key=>{const h=DATA.hotels[key],stay=DATA.days.filter(d=>d.hotel===key),first=stay[0],last=stay.at(-1),checkin=selectedPlan(first).find(r=>/入住/.test(r.stepTitle||'')),checkoutDay=DATA.days[last.id],checkout=checkoutDay?.timeline.find(r=>/退房/.test(r.stepTitle||'')),out=checkout&&stepWindow(checkoutDay,checkout);return {start:first.id,end:last.id,startAt:checkin?stepWindow(first,checkin)?.start:null,endAt:out?.end??out?.start??null,html:`<article class="tool-hotel"><p class="editor-label">${shortDate(stay[0].date)}${stay.length>1?' — '+shortDate(stay.at(-1).date):''} · 住宿</p>${hotelButton(key)}<p>${esc(h.address)}</p>${ext(hotelLink(key),'酒店导航','primary-link')}<button data-copy="${esc(h.name+'\n'+h.address)}">复制地址</button></article>`};}));if(k==='lists')return journeyToolGroups(TRAVEL_SUPPORT.purchases.map(p=>({start:p.day,end:p.day,html:`<article class="purchase-suggestion"><p class="editor-label">${shortDate(p.date)} · ${esc(p.time)}</p><h3>${esc(p.title)}</h3><div class="purchase-coverage">${p.coverage.map(c=>`<p><strong>${shortDate(c.date)}</strong> ${[['breakfast','早餐'],['lunch','午餐'],['dinner','晚餐']].filter(([k])=>c[k]).map(([k,n])=>n+'：'+esc(c[k])).join(' · ')}</p>`).join('')}</div><details class="journey-disclosure"><summary>食材搭配建议</summary><div class="journey-detail-body"><p>按人数、食量与喜好调整，可换成顺手买到的食材。</p><ul>${p.suggestions.map(x=>'<li>'+esc(x)+'</li>').join('')}</ul><p>${esc(p.reminder)}</p></div></details></article>`})));return previousToolBody(k);};

// Categorize presentation icons without changing itinerary objects.
function journeyStepKind(r){const title=r.stepTitle||'';if(/早餐|午餐|晚餐|海鲜|用餐|餐饮/.test(title))return 'food';if(/入住|退房|休息|泡浴|桑拿/.test(title))return 'bed';if(/取箱|行李|托运|候机|值机|安检/.test(title))return 'bag';if(/^飞|飞机|航班|登机|落地|抵达北京|转机/.test(title))return 'plane';if(/采购|购物/.test(title))return 'bag';if(/开车|自驾|驶|租车|验车|交车|还车|加油|隧道|机场|转场/.test(title))return 'car';if(/列车|地铁/.test(title))return 'train';if(/快艇|观鲸|追鲸/.test(title))return 'boat';if(/步行|漫步|徒步/.test(title))return 'walk';return 'pin';}
const r9OutlineIco=outlineIco;
// All step icons use the established 1.5px outline vocabulary.
function journeyTravelIcon(kind){if(kind==='train')return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="5" y="3" width="14" height="15" rx="3"/><path d="M5 11h14M9 3v8M15 3v8M8 21l2-3m6 3-2-3M8 15h1m6 0h1"/></svg>';if(kind==='boat')return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M4 13l8-3 8 3-2 6H6ZM7 12V6h10v6M12 3v3M2 21c2-2 4 2 6 0s4 2 6 0 4 2 8 0"/></svg>';return r9OutlineIco(kind);}
function emergencyContacts(){const dial=(label,num,display=num)=>`<a class="emergency-dial" href="tel:${num}"><span>${esc(label)}</span><strong>${esc(display)}</strong>${outlineIco('phone')}</a>`;return `<section class="emergency-contacts"><h2>紧急求助</h2><p>先说明所在位置、路号和人数。</p><h3>挪威</h3>${dial('医疗急救','113')}${dial('火警','110')}${dial('警方','112')}<h3>冰岛、芬兰、丹麦</h3>${dial('紧急求助','112')}<h2>京东安联保险</h2>${dial('境外热线','+8652780900000','+86 527 8090 0000')}${dial('境内热线','950610')}<p>救援范围与费用按保险合同处理。${ext('https://www.jdallianz.com/bxsc/product/detail?jdaz_chl=360&jdaz_realm=bxsc&jdaz_source=PC&p=2379','官方说明','')}</p><h2>道路救援</h2><p>租车故障先联系租车公司，安排救援前确认保险授权与费用。</p><h3>挪威 · REDGO</h3>${dial('挪威境内','98702222','987 02222')}${dial('国际拨号','+4733138080','+47 33 13 80 80')}<p>${ext('https://www.redgo.no/om-redgo/kontakt-oss','REDGO官方联系方式','')}</p><h3>冰岛 · FÍB Assistance</h3>${dial('道路救援','+3545112112','+354 5 112 112')}<p>FÍB会员救援服务；非会员及租赁车辆先询问是否受理和收费。${ext('https://www.fib.is/is/english','FÍB官方说明','')}</p></section>`;}
const r9OriginalEmergency=emergency;
emergency=function(){return emergencyContacts()+r9OriginalEmergency().replace(/<div class="callout danger">[\s\S]*?<\/div>/,'');};
const r9ToolBody=toolBody;
toolBody=function(k){if(k==='emergency')return emergency();if(k==='roads')return r9OriginalEmergency().replace(/<div class="callout danger">[\s\S]*?<\/div>/,'');if(k==='transport')return ['norway','iceland'].map(r=>`<details class="tool-disclosure"><summary>${r==='norway'?'挪威':'冰岛'}自驾、停车与罚单</summary><div class="rich">${markdown(DATA.guides[r])}</div></details>`).join('');const body=r9ToolBody(k);return k==='flights'?body+`<details class="tool-disclosure"><summary>赫尔辛基往返交通</summary>${helTransportDetail()}</details>`:body;};
